  it("handles null/undefined string", () => {
    expect(truncate(null as any, 5)).toBe("");
    expect(truncate(undefined as any, 5)).toBe("");
  });
});

describe("padLeft", () => {
  it("pads string with spaces by default", () => {
    expect(padLeft("hi", 5, " ")).toBe("   hi");
  });

